'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createHash}=require('node:crypto');
module.exports=function capture(repo,out){const phase=process.env.SIDEBAR_AUDIT_PHASE;assert.ok(['before','after'].includes(phase));const sha=b=>createHash('sha256').update(b).digest('hex');const original=require('../deep-audit-sidebar-layout/pins.json');const base=path.join(repo,'.artifacts/deep-audit-round2-sidebar-layout-fix');assert.equal(path.dirname(out),base,'Evidence root must be the new fix scope');const source=phase==='before'?path.join(base,'before-inputs'):repo;const destination=path.join(out,'source'),inputs={};assert.ok(!fs.existsSync(destination));
for(const name of Object.keys(original)){const bytes=fs.readFileSync(path.join(source,name));const hash=sha(bytes);assert.equal(hash,sha(fs.readFileSync(path.join(source,name))),'Input moved during capture '+name);if(phase==='before')assert.equal(hash,original[name]);const target=path.join(destination,name);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,bytes,{flag:'wx'});inputs[name]=hash;}
const retained=require(path.join(base,'before-inputs.json'));for(const[name,hash]of Object.entries(retained.acceptedEvidence))assert.equal(sha(fs.readFileSync(path.join(repo,name))),hash,'Original accepted evidence changed: '+name);
const harness={};const fixture='tests/fixtures/deep-audit-sidebar-layout-fix';for(const name of ['tests/deep-audit-sidebar-layout-fix.test.cjs',...fs.readdirSync(path.join(repo,fixture)).map(n=>fixture+'/'+n)]){if(!fs.statSync(path.join(repo,name)).isFile())continue;const bytes=fs.readFileSync(path.join(repo,name)),target=path.join(out,'harness',name);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,bytes,{flag:'wx'});harness[name]=sha(bytes);}
fs.writeFileSync(path.join(out,'source-manifest.json'),JSON.stringify({phase,source:phase==='before'?'exact preserved original input bytes':'current maintained source captured into per-run immutable copy',inputs,harness},null,2),{flag:'wx'});
};
